CREATE POLICY staff_abc_xyz_classification_all ON public.abc_xyz_classification AS PERMISSIVE FOR ALL TO authenticated USING ((has_role(auth.uid(), 'master'::app_role) OR has_role(auth.uid(), 'employee'::app_role) OR has_role(auth.uid(), 'master'::app_role) OR has_role(auth.uid(), 'master'::app_role))) WITH CHECK ((has_role(auth.uid(), 'master'::app_role) OR has_role(auth.uid(), 'employee'::app_role) OR has_role(auth.uid(), 'master'::app_role) OR has_role(auth.uid(), 'master'::app_role)));
CREATE POLICY "Staff fecha execucao propria" ON public.acoes_execucoes AS PERMISSIVE FOR UPDATE TO public USING (((has_role(auth.uid(), 'master'::app_role) OR has_role(auth.uid(), 'employee'::app_role)) AND (executado_por = auth.uid()))) WITH CHECK (((has_role(auth.uid(), 'master'::app_role) OR has_role(auth.uid(), 'employee'::app_role)) AND (executado_por = auth.uid())));
CREATE POLICY "Staff le execucoes" ON public.acoes_execucoes AS PERMISSIVE FOR SELECT TO public USING ((has_role(auth.uid(), 'master'::app_role) OR has_role(auth.uid(), 'employee'::app_role)));
CREATE POLICY "Staff registra execucao propria" ON public.acoes_execucoes AS PERMISSIVE FOR INSERT TO public WITH CHECK (((has_role(auth.uid(), 'master'::app_role) OR has_role(auth.uid(), 'employee'::app_role)) AND (executado_por = auth.uid()) AND (origem = 'manual'::text)));
CREATE POLICY "Employees can view all addresses" ON public.addresses AS PERMISSIVE FOR SELECT TO public USING ((has_role(auth.uid(), 'master'::app_role) OR has_role(auth.uid(), 'employee'::app_role)));
