CREATE POLICY "call_log team select" ON public.call_log AS PERMISSIVE FOR SELECT TO public USING ((has_role(auth.uid(), 'master'::app_role) OR (EXISTS ( SELECT 1
   FROM commercial_roles cr
  WHERE ((cr.user_id = auth.uid()) AND (cr.commercial_role = ANY (ARRAY['gerencial'::commercial_role, 'estrategico'::commercial_role, 'super_admin'::commercial_role])))))));
